window.kbPageData["views/entry/k-20e96d249dc0741a"] = {"key":"entry/k-20e96d249dc0741a","state":{"route":"entry/k-20e96d249dc0741a"},"node":{"id":"k-20e96d249dc0741a","mode":"k","title":"自动投案","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["自动投案的时点、主动性与受理机关"],"qs":["国考 2025 行政执法 行测#88"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"犯罪事实或者犯罪嫌疑人未被司法机关发觉，或虽已被发觉，但嫌疑人就该案尚未受到讯问、未被采取强制措施时，主动、直接向公安机关、人民检察院或者人民法院投案，属于自动投案。司法解释还规定了视为自动投案的情形。","review":{"definition":"犯罪事实或者犯罪嫌疑人未被司法机关发觉，或虽已被发觉，但嫌疑人就该案尚未受到讯问、未被采取强制措施时，主动、直接向公安机关、人民检察院或者人民法院投案，属于自动投案。司法解释还规定了视为自动投案的情形。","explanation":"按题给定义，乙已被确认为伤害案嫌疑人，经该案讯问才交代，因此选B。酒驾行政拘留期间主动交代尚未被掌握的犯罪，依法仍可能视为自动投案。A项仅因形迹可疑被一般盘问后主动交代，若罪行尚未被发觉，且盘查中未发现与犯罪有关的物品，可以视为自动投案。D项在司法认定中适用服刑人员供述余罪的规则，若丁如实供述司法机关尚未掌握的本人走私罪行，并与原判盗窃罪属不同种罪行，则依法以自首论。题解将D项归入题给定义的做法，适用范围限于本题。","references":[{"source":"web-e0bdd7ce68b42002","location":"第一部分、第三部分","quote":"主动向执行机关交代尚未被掌握的犯罪行为"},{"source":"web-6922d99a0cff2a52","location":"第六十七条第二款","quote":"如实供述司法机关还未掌握的本人其他罪行"}],"evidence":"主动、直接向公安机关、人民检察院或者人民法院投案","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2025 行政执法 行测#88":{"paper":"国考 2025 行政执法 行测","n":88,"mod":"判断推理","src":["d8efe4e19862104d89c8.pdf",17],"asrc":["e2c4b1970d2b49eac0fd.pdf",28],"card":"7859b6358e8feba9108bc8c4","links":[{"id":"k-20e96d249dc0741a","role":"解题依据","why":"已被发觉时，是否在针对该案的讯问或采取强制措施之前主动投案，是认定自动投案的条件。"}]}},"terms":{},"references":{"web-e0bdd7ce68b42002":{"name":"最高人民法院关于处理自首和立功若干具体问题的意见","url":"https://www.court.gov.cn/fabu/xiangqing/2484.html"},"web-6922d99a0cff2a52":{"name":"中华人民共和国刑法","url":"https://www.lyjjw.gov.cn/sitesources/lysjwjcw/page_pc/xsqjw/lcq/djfg/article4c9b8261d4de45809602d1e2649c59d5.html"}},"topics":[],"units":{"k-20e96d249dc0741a":[["国考 2025 行政执法 行测#88"]]}};
